"""Summarize header presence for the seeded sample of path-detected generated files (out/header_fetch.csv) and the
visibility of those files to the HeaderGuard baseline rules (regex copied from genlineage/agent.py looks_generated).
Run: venv/bin/python -I build/inthewild/header_stats.py out/"""
import csv, glob, hashlib, json, math, os, re, sys
OUT = sys.argv[1]
HDR = re.compile(r"(code generated .*do not edit|@generated|do not edit|auto-generated|this file was generated|<auto-generated>|generated by \S+)", re.I)
HDR_OK = re.compile(r"(edit freely|safe to edit|do not edit without|generated by (hand|chatgpt))", re.I)
NAME = re.compile(r"(_pb2\.py|_pb2_grpc\.py|\.pb\.go)$")
def wilson(k, n, z=1.96):
    if not n: return None
    p = k / n; d = 1 + z * z / n; c = p + z * z / (2 * n); h = z * math.sqrt(p * (1 - p) / n + z * z / (4 * n * n))
    return [round((c - h) / d, 4), round((c + h) / d, 4)]
rows = list(csv.DictReader(open(os.path.join(OUT, "header_fetch.csv"))))
avail = [r for r in rows if r["hdr_fetched"] != "unavailable"]
res = {"sampled": len(rows), "fetched": len(avail)}
for cls in ("strong", "weak", "none"):
    k = sum(r["hdr_fetched"] == cls for r in avail); res[cls] = k; res[cls + "_rate"] = round(k / len(avail), 4); res[cls + "_ci95"] = wilson(k, len(avail))
vis = 0
for r in avail:
    rec = json.load(open(os.path.join(OUT, "header_cache", hashlib.sha1((r["pr_id"] + r["file"]).encode()).hexdigest() + ".json")))
    head = "\n".join(rec["lines"][:15])
    v = bool(NAME.search(r["file"])) or (bool(HDR.search(head)) and not HDR_OK.search(head)); vis += v
res["headerguard_visible"] = vis; res["headerguard_invisible"] = len(avail) - vis
res["headerguard_invisible_rate"] = round((len(avail) - vis) / len(avail), 4); res["headerguard_invisible_ci95"] = wilson(len(avail) - vis, len(avail))
res["used_head_commit"] = sum(r["fetched"] == "head" for r in avail); res["used_last_commit"] = sum(r["fetched"] == "last_commit" for r in avail)
by_rule = {}
for r in avail: by_rule.setdefault(r["path_rule"], [0, 0])[0 if r["hdr_fetched"] == "strong" else 1] += 1
res["by_rule_strong_vs_not"] = by_rule
# audit
a = list(csv.DictReader(open(os.path.join(os.path.dirname(OUT.rstrip('/')), "sample_audit.csv"))))
from collections import Counter
c = Counter(r["judgment"] for r in a); res["audit"] = dict(c); res["audit_n"] = len(a)
res["audit_hand_edit_lost_ci95"] = wilson(c["hand_edit_lost"], len(a)); res["audit_truly_generated"] = sum(r["truly_generated"] == "yes" for r in a)
json.dump(res, open(os.path.join(OUT, "header_summary.json"), "w"), indent=1); print(json.dumps(res, indent=1))
# robustness: same classifier over the first 40 fetched lines instead of 15
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from gendetect import HDR_GO, HDR_AT, HDR_CS, HDR_GEN, HDR_NOEDIT
def strong40(lines):
    w = "\n".join(lines[:40]); return bool(HDR_GO.search(w) or HDR_AT.search(w) or HDR_CS.search(w) or (HDR_GEN.search(w) and HDR_NOEDIT.search(w)))
k40 = vis40 = 0
for r in avail:
    rec = json.load(open(os.path.join(OUT, "header_cache", hashlib.sha1((r["pr_id"] + r["file"]).encode()).hexdigest() + ".json")))
    L = rec["lines"]; k40 += strong40(L)
    head = "\n".join(L[:40]); vis40 += bool(NAME.search(r["file"])) or (bool(HDR.search(head)) and not HDR_OK.search(head))
res["strong_40_lines"] = k40; res["no_strong_40_lines_rate"] = round(1 - k40 / len(avail), 4); res["no_strong_40_ci95"] = wilson(len(avail) - k40, len(avail))
res["headerguard_invisible_40_lines"] = len(avail) - vis40; res["headerguard_invisible_40_rate"] = round((len(avail) - vis40) / len(avail), 4)
json.dump(res, open(os.path.join(OUT, "header_summary.json"), "w"), indent=1)
print("40-line window:", k40, res["no_strong_40_lines_rate"], res["no_strong_40_ci95"], res["headerguard_invisible_40_lines"], res["headerguard_invisible_40_rate"])
